def is_permutation(a, c, p):
    """Checks if P(x) = ax^3 + cx is a permutation polynomial modulo p."""
    if p <= 1:
        return False

    values = set()
    for x in range(p):
        y = (a * x**3 + c * x) % p
        if y in values:
            return False
        values.add(y)
    return True

