def is_pp_mod_3(a, c):
    # P(x) = ax^3 + cx mod 3
    # Since x^3 = x mod 3, P(x) = (a+c)x mod 3
    slope = (a + c) % 3
    # PP iff slope is non-zero mod 3
    return slope != 0

count_n3 = 0
for a in range(3):
    for c in range(3):
        if is_pp_mod_3(a, c):
            count_n3 += 1

print(f"Count N3 for modulo 3: {count_n3}")

